// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzzed parameters: an address for the 'from' (as EOA), and a uint8 n for _tos length,
    // and a flag shouldRevert to make the callee revert or succeed. We will construct
    // an array of addresses of length n and fill with the recorder/reverter contract.
    function testFuzz_property(address from, uint8 n, bool shouldRevert) public {
        // keep domain wide but sensible: require at least 1 length to exercise require(_tos.length>0)
        vm.assume(n > 0);
        // deploy helper that either records calls or reverts depending on shouldRevert
        Helper helper = new Helper(shouldRevert);

        // build dynamic address[] memory _tos of length n, all pointing to helper
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            tos[i] = address(helper);
        }

        // call c.transfer and capture whether it reverted or not
        bool ok;
        try c.transfer(from, address(helper), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assert): For the reference contract, for any non-empty _tos and a callee
        // that either succeeds or reverts reliably, transfer should NOT revert when the callee is set to succeed.
        // We therefore assert: if helper is configured to NOT revert, transfer must succeed (ok == true).
        // The mutant that changes loop bound to i<=_tos.length will sometimes revert (when it attempts
        // to access tos[n]) and thus fail this assertion for some fuzz inputs (various n).
        if (!shouldRevert) {
            assertTrue(ok);
        } else {
            // when callee reverts, behavior may be revert both in ref and mutant; we don't assert in that case
            // to keep the property universally quantified only over the success-callege scenario.
            // Do nothing.
        }
    }
}

// Helper that optionally reverts on the expected selector or records calls.
contract Helper {
    bool public shouldRevert;
    uint256 public calls;
    event Called(address from, address to, uint256 v);

    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }

    // match the selector transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        if (shouldRevert) revert("forced");
        calls += 1;
        emit Called(from, to, v);
        return true;
    }

    // fallback to catch malformed calls (not expected here)
    fallback() external payable {
        if (shouldRevert) revert("forced");
        calls += 1;
    }
}
